/*
 * atg_kc705_mig: The KC705 memory: MIG 7 Series DDR3 (1 GB, 64 bit, AXI4
 * 512 bit, ui_clk 200 MHz, regenerated by TCL, design §4.1) behind an AXI4
 * slave in gclk (the clock crossing to ui_clk is inside: MIG's AXI clock
 * converter or an AXI clock converter IP, chosen in p012).  See
 * spec/boards/kc705/lib/atg_kc705_mig.md.
 *
 * Two IP cores, generated by the part-B TCL (not committed) under these
 * module names and with this configuration:
 *
 *   atg_kc705_axi_cc   AXI Clock Converter: AXI4, ID width 0, address 32,
 *                      data 512, asynchronous clocks (gclk -> ui_clk).
 *   atg_kc705_ddr3     MIG 7 Series, the board file's DDR3 preset (64 bit,
 *                      800 MHz, 4:1, ui_clk 200 MHz) with the AXI4
 *                      interface (data 512, address 30, ID 4), system
 *                      clock "No Buffer" (ref_clk from atg_kc705_clk), the
 *                      reference clock "Use System Clock", sys_rst active
 *                      low, XADC on (device_temp).
 *
 * The IDs are 0 (atg_top has one ID).  The MIG's AXI reset (aresetn) is
 * ui_clk_sync_rst inverted and registered in ui_clk; the converter's
 * master side uses it too.  mem_ready is init_calib_complete in gclk
 * through am_sync.  The port names of both cores follow their product
 * guides (PG089 MIG AXI, PG164 clock converter) as remembered: they are
 * checked when part B generates the cores (Unverified until then).  In
 * simulation this whole module is replaced by sim/models/kc705/
 * atg_kc705_mig.v (an axi_mem in gclk).
 */

`timescale 1ns / 1ps
`default_nettype none

module atg_kc705_mig (
	input wire clk,
	input wire rst_n,
	input wire sys_clk,
	input wire sys_rst_n,
	output wire mem_ready,
	/* AXI4 slave (gclk), atg_top's m_* */
	input wire [31:0] s_awaddr,
	input wire [7:0] s_awlen,
	input wire [2:0] s_awsize,
	input wire [1:0] s_awburst,
	input wire [3:0] s_awcache,
	input wire [2:0] s_awprot,
	input wire s_awvalid,
	output wire s_awready,
	input wire [511:0] s_wdata,
	input wire [63:0] s_wstrb,
	input wire s_wlast,
	input wire s_wvalid,
	output wire s_wready,
	output wire [1:0] s_bresp,
	output wire s_bvalid,
	input wire s_bready,
	input wire [31:0] s_araddr,
	input wire [7:0] s_arlen,
	input wire [2:0] s_arsize,
	input wire [1:0] s_arburst,
	input wire [3:0] s_arcache,
	input wire [2:0] s_arprot,
	input wire s_arvalid,
	output wire s_arready,
	output wire [511:0] s_rdata,
	output wire [1:0] s_rresp,
	output wire s_rlast,
	output wire s_rvalid,
	input wire s_rready,
	/* DDR3 pins */
	inout wire [63:0] ddr3_dq,
	inout wire [7:0] ddr3_dqs_p,
	inout wire [7:0] ddr3_dqs_n,
	output wire [13:0] ddr3_addr,
	output wire [2:0] ddr3_ba,
	output wire ddr3_ras_n,
	output wire ddr3_cas_n,
	output wire ddr3_we_n,
	output wire ddr3_reset_n,
	output wire ddr3_ck_p,
	output wire ddr3_ck_n,
	output wire ddr3_cke,
	output wire ddr3_cs_n,
	output wire [7:0] ddr3_dm,
	output wire ddr3_odt
);
	wire ui_clk, ui_rst, calib;
	reg aresetn = 1'b0;

	always @(posedge ui_clk)
		aresetn <= !ui_rst;

	am_sync sync_ready (.clk(clk), .rst_n(rst_n), .d(calib), .q(mem_ready));

	/* The converter's master side, in ui_clk. */
	wire [31:0] u_awaddr, u_araddr;
	wire [7:0] u_awlen, u_arlen;
	wire [2:0] u_awsize, u_arsize, u_awprot, u_arprot;
	wire [1:0] u_awburst, u_arburst, u_bresp, u_rresp;
	wire [3:0] u_awcache, u_arcache, u_awqos, u_arqos;
	wire [0:0] u_awlock, u_arlock;
	wire u_awvalid, u_awready, u_wlast, u_wvalid, u_wready, u_bvalid, u_bready;
	wire u_arvalid, u_arready, u_rlast, u_rvalid, u_rready;
	wire [511:0] u_wdata, u_rdata;
	wire [63:0] u_wstrb;

	atg_kc705_axi_cc cc (
		.s_axi_aclk(clk), .s_axi_aresetn(rst_n),
		.s_axi_awaddr(s_awaddr), .s_axi_awlen(s_awlen), .s_axi_awsize(s_awsize),
		.s_axi_awburst(s_awburst), .s_axi_awlock(1'b0), .s_axi_awcache(s_awcache),
		.s_axi_awprot(s_awprot), .s_axi_awregion(4'd0), .s_axi_awqos(4'd0),
		.s_axi_awvalid(s_awvalid), .s_axi_awready(s_awready),
		.s_axi_wdata(s_wdata), .s_axi_wstrb(s_wstrb), .s_axi_wlast(s_wlast),
		.s_axi_wvalid(s_wvalid), .s_axi_wready(s_wready),
		.s_axi_bresp(s_bresp), .s_axi_bvalid(s_bvalid), .s_axi_bready(s_bready),
		.s_axi_araddr(s_araddr), .s_axi_arlen(s_arlen), .s_axi_arsize(s_arsize),
		.s_axi_arburst(s_arburst), .s_axi_arlock(1'b0), .s_axi_arcache(s_arcache),
		.s_axi_arprot(s_arprot), .s_axi_arregion(4'd0), .s_axi_arqos(4'd0),
		.s_axi_arvalid(s_arvalid), .s_axi_arready(s_arready),
		.s_axi_rdata(s_rdata), .s_axi_rresp(s_rresp), .s_axi_rlast(s_rlast),
		.s_axi_rvalid(s_rvalid), .s_axi_rready(s_rready),
		.m_axi_aclk(ui_clk), .m_axi_aresetn(aresetn),
		.m_axi_awaddr(u_awaddr), .m_axi_awlen(u_awlen), .m_axi_awsize(u_awsize),
		.m_axi_awburst(u_awburst), .m_axi_awlock(u_awlock), .m_axi_awcache(u_awcache),
		.m_axi_awprot(u_awprot), .m_axi_awregion(), .m_axi_awqos(u_awqos),
		.m_axi_awvalid(u_awvalid), .m_axi_awready(u_awready),
		.m_axi_wdata(u_wdata), .m_axi_wstrb(u_wstrb), .m_axi_wlast(u_wlast),
		.m_axi_wvalid(u_wvalid), .m_axi_wready(u_wready),
		.m_axi_bresp(u_bresp), .m_axi_bvalid(u_bvalid), .m_axi_bready(u_bready),
		.m_axi_araddr(u_araddr), .m_axi_arlen(u_arlen), .m_axi_arsize(u_arsize),
		.m_axi_arburst(u_arburst), .m_axi_arlock(u_arlock), .m_axi_arcache(u_arcache),
		.m_axi_arprot(u_arprot), .m_axi_arregion(), .m_axi_arqos(u_arqos),
		.m_axi_arvalid(u_arvalid), .m_axi_arready(u_arready),
		.m_axi_rdata(u_rdata), .m_axi_rresp(u_rresp), .m_axi_rlast(u_rlast),
		.m_axi_rvalid(u_rvalid), .m_axi_rready(u_rready)
	);

	atg_kc705_ddr3 ddr3 (
		.ddr3_dq(ddr3_dq), .ddr3_dqs_n(ddr3_dqs_n), .ddr3_dqs_p(ddr3_dqs_p),
		.ddr3_addr(ddr3_addr), .ddr3_ba(ddr3_ba), .ddr3_ras_n(ddr3_ras_n),
		.ddr3_cas_n(ddr3_cas_n), .ddr3_we_n(ddr3_we_n), .ddr3_reset_n(ddr3_reset_n),
		.ddr3_ck_p(ddr3_ck_p), .ddr3_ck_n(ddr3_ck_n), .ddr3_cke(ddr3_cke),
		.ddr3_cs_n(ddr3_cs_n), .ddr3_dm(ddr3_dm), .ddr3_odt(ddr3_odt),
		.sys_clk_i(sys_clk), .sys_rst(sys_rst_n),
		.ui_clk(ui_clk), .ui_clk_sync_rst(ui_rst), .mmcm_locked(),
		.aresetn(aresetn), .app_sr_req(1'b0), .app_ref_req(1'b0), .app_zq_req(1'b0),
		.app_sr_active(), .app_ref_ack(), .app_zq_ack(),
		.init_calib_complete(calib), .device_temp(),
		.s_axi_awid(4'd0), .s_axi_awaddr(u_awaddr[29:0]), .s_axi_awlen(u_awlen),
		.s_axi_awsize(u_awsize), .s_axi_awburst(u_awburst), .s_axi_awlock(u_awlock),
		.s_axi_awcache(u_awcache), .s_axi_awprot(u_awprot), .s_axi_awqos(u_awqos),
		.s_axi_awvalid(u_awvalid), .s_axi_awready(u_awready),
		.s_axi_wdata(u_wdata), .s_axi_wstrb(u_wstrb), .s_axi_wlast(u_wlast),
		.s_axi_wvalid(u_wvalid), .s_axi_wready(u_wready),
		.s_axi_bready(u_bready), .s_axi_bid(), .s_axi_bresp(u_bresp), .s_axi_bvalid(u_bvalid),
		.s_axi_arid(4'd0), .s_axi_araddr(u_araddr[29:0]), .s_axi_arlen(u_arlen),
		.s_axi_arsize(u_arsize), .s_axi_arburst(u_arburst), .s_axi_arlock(u_arlock),
		.s_axi_arcache(u_arcache), .s_axi_arprot(u_arprot), .s_axi_arqos(u_arqos),
		.s_axi_arvalid(u_arvalid), .s_axi_arready(u_arready),
		.s_axi_rready(u_rready), .s_axi_rid(), .s_axi_rdata(u_rdata), .s_axi_rresp(u_rresp),
		.s_axi_rlast(u_rlast), .s_axi_rvalid(u_rvalid)
	);

	/* The MIG's 1 GB takes address bits 29:0. */
	wire unused_ok = &{1'b0, u_awaddr[31:30], u_araddr[31:30]};
endmodule

`default_nettype wire
